/**
 * @file explore/logo.js - page script of explore/logo.html, the logo seed generator (Debug / LogoDesign).
 *
 * Entry: `<body onload="logoMain()">`. First the icon, logo and banner this app uses (icon.svg, square, logo.svg, 4:3, and banner.svg,
 * 9:2: generated by the server from the app name / seed unless the app serves its own; --sw-brand-icon / --sw-brand-logo of
 * ui/tokens.css, the banner as an img). Below it, clearly labelled as a generator, the server's generated logos: the current app seed
 * (`Api/debug/explore/GetAppSeed`) as the first, highlighted tile and 9 tiles with random 31-bit seeds (images `logo_debug.svg?<seed>`).
 * Selecting a tile (click, Enter / Space) copies its seed and swaps it into the first slot; "Randomize" (or the R key) creates 9 new
 * candidates. Tiles are titled "Current seed" / "Variant n" with the seed as a secondary line ("Seed 123", seed 0 = "Default design
 * (seed 0)") and in the tool tip, and show the palette of the seed's application theme (four squares: background, main, accent 1,
 * accent 2; `Api/debug/explore/GetSeedColors`, one request per set). The floating palette button at the top right of a tile (a sibling of
 * the tile button, div.logo-cell) previews the seed's theme: explore/themepreview.html in a dialog, with
 * `useTheme=application@../Api/debug/explore/PreviewTheme.css%3F<seed>` (forced for that frame only, never stored as the user's theme).
 * The intro says what a seed changes (device neutral words: "select"). Uses Sw (sw/core.js + sw/ui.js).
 * Styled by explore/icons.css (tiles) and explore/logo.css.
 */

(() => {
    "use strict";

    const Sw = window.Sw;
    const el = Sw.el;

    /** Number of tiles. */
    const Count = 10;

    /**
     * Page entry of explore/logo.html.
     * @returns {Promise<void>} Resolves when the first set of images is loaded.
     */
    window.logoMain = async function () {
        const remove = Sw.Page.Loading();
        try {
            const pending = new Sw.PendingImages();
            let selected = String(await Sw.Net.Get(Sw.Net.Api("debug/explore/GetAppSeed")));
            //  The tiles are buttons (select and copy), grouped (a list of buttons was announced as plain list items)
            const list = el("div.icons-list.logo-list", { attrs: { role: "group", "aria-label": _TF("Logo seeds", "Accessible name of the group of logo tiles in the logo designer") } });

            /** @type {Map<string, object>} The four base colours of the application theme per seed (Api debug/explore/GetSeedColors). */
            const colors = new Map();

            /**
             * Show the palette of a tile's seed: the four base colours of its application theme as squares (background, main, accent 1,
             * accent 2), when they are known (loadColors).
             * @param {HTMLElement} tile The tile.
             */
            const setPalette = tile => {
                const c = colors.get(tile.SwSeed);
                const sw = (v, name) => el("span.logo-swatch", { style: { backgroundColor: v }, title: name + ": " + v });
                tile.SwPalette.replaceChildren(...(c ? [
                    sw(c.Background, _TF("Background", "Name of the background colour of a palette in the logo designer")),
                    sw(c.Main, _TF("Main", "Name of the main (text) colour of a palette in the logo designer")),
                    sw(c.Acc1, _TF("Accent 1", "Name of the first accent colour of a palette in the logo designer")),
                    sw(c.Acc2, _TF("Accent 2", "Name of the second accent colour of a palette in the logo designer")),
                ] : []));
            };

            /**
             * Fetch the colours of the seeds that are not known yet (one request) and show the palettes.
             * @returns {Promise<void>}
             */
            const loadColors = async () => {
                const tiles = Array.from(list.querySelectorAll(".icons-item"));
                const need = [...new Set(tiles.map(t => t.SwSeed).filter(s => !colors.has(s)))];
                if (need.length) {
                    const r = await Sw.Net.Send(Sw.Net.Api("debug/explore/GetSeedColors"), need.map(s => parseInt(s, 10)));
                    (r || []).forEach(c => colors.set(String(c.Seed), c));
                }
                tiles.forEach(setPalette);
            };

            /**
             * Show the theme of a seed: the demo app (explore/themepreview.html) in a dialog, with the seed's application theme
             * ("useTheme": forced for that frame only, never stored as the user's theme).
             * @param {string} seed The seed.
             */
            const preview = seed => {
                //  (the theme value as Sw.Theme reads it: a literal "name@css url", only the "?" of the css url encoded; an encoded "@" / "/"
                //  is not split into the theme name and its css, so the frame kept the selected theme)
                const s0 = String(parseInt(seed, 10) || 0);
                const frame = el("iframe.logo-preview-frame", {
                    src: "themepreview.html?seed=" + s0 + "&useTheme=application@../Api/debug/explore/PreviewTheme.css%3F" + s0,
                    title: _T("Theme preview of the seed {0}", s0, "Accessible name of the frame with the theme preview in the logo designer, {0} is the seed"),
                });
                //  Prev / Next walk through seeds: index -> seed (key 0 = the seed the preview was opened with); a new index gets a new
                //  random seed, an index seen before shows its seed again (the index may go below zero)
                const seeds = new Map([[0, s0]]);
                let index = 0;
                let cur = s0;
                const seedBtn = new Sw.Button({
                    Text: s0, Kind: "ghost", Small: true, Icon: "copy", Class: "logo-preview-seed",
                    Title: _TF("Copy the seed and make it the current seed", "Tool tip of the seed button in the window bar of the theme preview of the logo designer"),
                    OnClick: () => select(cur),
                });
                /**
                 * Show the seed of an index (creating a random one for a new index): the theme, the marks and the window bar.
                 * @param {number} i The index.
                 */
                const go = i => {
                    index = i;
                    if (!seeds.has(index))
                        seeds.set(index, randomSeed());
                    cur = seeds.get(index);
                    seedBtn.SetText(cur);
                    frame.title = _T("Theme preview of the seed {0}", cur, "Accessible name of the frame with the theme preview in the logo designer, {0} is the seed");
                    const w = frame.contentWindow;
                    if (w && typeof w.themePreviewSeed === "function")
                        w.themePreviewSeed(cur);
                };
                const prev = new Sw.Button({
                    Icon: "left", Kind: "ghost", Small: true,
                    Title: _TF("Previous seed", "Tool tip of the button in the window bar of the theme preview of the logo designer that shows the previous seed"),
                    OnClick: () => go(index - 1),
                });
                const next = new Sw.Button({
                    Icon: "right", Kind: "ghost", Small: true,
                    Title: _TF("Next seed (a new random seed)", "Tool tip of the button in the window bar of the theme preview of the logo designer that shows the next seed"),
                    OnClick: () => go(index + 1),
                });
                Sw.Dialog.Open({
                    //  (the seed is shown once: the copy button between Prev and Next in the window bar)
                    Title: _TF("Theme preview", "Title of the theme preview dialog of the logo designer (the seed is on the button next to it)"),
                    Icon: "palette", Wide: true, Full: true, Class: "logo-preview", Id: "explore.logo.preview",
                    Content: (body, close, tools) => {
                        tools.prepend(el("div.logo-preview-nav", { attrs: { role: "group", "aria-label": _TF("Seed", "Accessible name of the seed buttons in the window bar of the theme preview") } }, prev.E, seedBtn.E, next.E));
                        return frame;
                    },
                });
            };

            /** @returns {string} A new random 31-bit seed. */
            const randomSeed = () => String(Math.floor(Math.random() * 2147483647) | 0);

            /**
             * Make a seed the current one, as a click on its tile: copy it and show it in the first tile ("Current seed"). A seed of a
             * tile swaps places with the current one; another seed (ex: from the theme preview) takes the first tile.
             * @param {string} seed The seed.
             * @returns {Promise<void>}
             */
            const select = async seed => {
                selected = seed;
                await Sw.Clipboard.Copy(seed);
                const tiles = Array.from(list.querySelectorAll(".icons-item"));
                const first = tiles[0];
                if (!first || first.SwSeed === seed)
                    return;
                const old = first.SwSeed;
                const t = tiles.find(x => x.SwSeed === seed);
                setSeed(first, seed);
                if (t)
                    setSeed(t, old);
                loadColors().catch(e => Sw.DevWarn("App theme: the seed colours: " + (e && e.message ? e.message : e), "logo.colors"));
            };

            /**
             * Set the seed of a tile.
             * @param {HTMLElement} tile The tile.
             * @param {string} seed The seed.
             */
            const setSeed = (tile, seed) => {
                tile.SwSeed = seed;
                pending.Start(tile.SwImg, Sw.Url.Root + "logo_debug.svg?" + seed);
                setPalette(tile);
                tile.SwPreview.SetTitle(_T("Preview the theme of the seed {0}", seed, "Tool tip of the preview button of a logo tile in the logo designer, {0} is the seed of the logo"));
                //  Seed 0 is the built-in design (no seed set): "Seed 0" next to 10 digit seeds read like an error
                tile.SwSeedText.textContent = seed === "0"
                    ? _TF("Default design (seed 0)", "Secondary text of the logo tile in the logo designer whose seed is 0: the built-in default logo design")
                    : _T("Seed {0}", seed, "Secondary text of a logo tile in the logo designer, {0} is the number (seed) that the logo is generated from");
                //  The button is named by its visible text ("Variant 3, Seed 123"); the tool tip (its description) says what selecting does
                tile.title = _T("Select to use the seed {0} (copies it to the clipboard)", seed, "Tool tip of a logo tile in the logo designer, {0} is the seed of the logo");
            };

            /**
             * Create a tile.
             * @param {number} index The tile index (0 = the selected seed).
             * @returns {HTMLElement} The tile.
             */
            const tile = index => {
                const img = Sw.CreateImg();
                img.draggable = false;
                img.alt = "";
                //  A friendly title ("Current logo", "Variant 3"); the seed is the secondary line (and in the tool tip)
                const text = el("div.icons-name", {
                    text: index === 0
                        ? _TF("Current seed", "Title of the first generated logo tile in the logo generator (the app seed in use)")
                        : _T("Variant {0}", index, "Title of a logo tile in the logo designer, {0} is the number of the tile (1..9)"),
                });
                const seedText = el("div.logo-seed");
                //  The four base colours of the seed's application theme (filled by setPalette)
                const palette = el("div.logo-palette", { attrs: { "aria-hidden": "true" } });
                const t = el("div.icons-item", { tabIndex: 0, attrs: { role: "button" } }, img, text, seedText, palette);
                t.SwImg = img;
                t.SwSeedText = seedText;
                t.SwPalette = palette;
                //  The floating preview button (top right; a sibling of the tile, a button is never inside another button)
                t.SwPreview = new Sw.Button({
                    Icon: "palette", Kind: "ghost", Small: true, OnClick: () => preview(t.SwSeed),
                    Title: _TF("Preview the theme", "Tool tip of the preview button of a logo tile in the logo designer"),
                });
                t.SwPreview.E.classList.add("logo-previewbtn");
                Sw.KeyClick(t, ev => {
                    if (!Sw.BadClick(ev))
                        return select(t.SwSeed);
                });
                return el("div.logo-cell", null, t, t.SwPreview.E);
            };

            /** Create the tiles: the selected seed plus random candidates. */
            const create = () => {
                const cells = [];
                for (let i = 0; i < Count; ++i) {
                    const c = tile(i);
                    setSeed(c.firstElementChild, i === 0 ? selected : randomSeed());
                    cells.push(c);
                }
                list.replaceChildren(...cells);
                loadColors().catch(e => Sw.DevWarn("App theme: the seed colours: " + (e && e.message ? e.message : e), "logo.colors"));
            };
            const rnd = new Sw.Button({
                Text: _TF("Randomize", "The text of a button that when clicked will show 10 new random logos"),
                Title: _TF("Show new random logos", "The tool tip description on a button that when selected will show 10 new random logos") + " (R)",
                Icon: "IconDice",
                OnClick: create,
            });
            document.addEventListener("keydown", ev => {
                if ((ev.key === "r" || ev.key === "R") && Sw.IsPureEvent(ev) && !/INPUT|TEXTAREA/.test(document.activeElement.tagName))
                    create();
            });
            //  Design v2 page (ui/page.css): a page header, then two cards: the icon and logo in use and the generator, labelled
            //  as such (device neutral words: "select"); Randomize is the generator card's action
            const header = Sw.PageHeader({
                Title: _TF("App theme", "Title of the app theme page (the app icon, logo, banner and colours, generated from a seed)"),
                Description: _TF("The icon, logo and banner this app uses, and the logos and themes the service can generate from other seeds.", "Description of the logo designer page"),
            });
            const brand = el("section.sw-card.logo-brand", { attrs: { "aria-labelledby": "logo-brand-head" } },
                el("div.sw-card-head", null, el("h2.logo-head", { id: "logo-brand-head", text: _TF("Icon, logo and banner in use", "Heading of the panel with the app icon, logo and banner at the top of the logo generator") })),
                el("div.sw-card-body", null,
                    el("div.logo-brand-marks", null,
                        el("div.sw-brand-mark.logo-brand-mark", { attrs: { role: "img", "aria-label": _TF("App icon", "Accessible name of the app icon picture in the logo generator") } }),
                        el("div.sw-brand-logo.logo-brand-logo", { attrs: { role: "img", "aria-label": _TF("App logo", "Accessible name of the app logo picture in the logo generator") } }),
                        //  (the real file: its own aspect ratio, 9:2 for the generated banner)
                        el("img.logo-brand-banner", { src: Sw.Url.Root + "banner.svg", alt: _TF("App banner", "Accessible name of the app banner picture in the logo generator"), draggable: false })),
                    el("p.logo-note", { text: _TF("The service generates them from the app seed (the first tile below), unless the app serves its own icon.svg / logo.svg / banner.svg. They are used for the browser tab, the install icons, the menu, Welcome and the sign in page.", "Text below the app icon, logo and banner in the logo generator") })));
            const genHead = el("h2.logo-head", { id: "logo-gen-head", text: _TF("Logo generator", "Heading of the generated logos section of the logo generator page") });
            const intro = el("p.logo-intro", { text: _TF("The service draws the logo and the colours of the application theme from a seed (the app seed, AppInfo AppSeed). Select a logo to copy its seed, the palette button to preview its theme, Randomize for more.", "Introduction of the generated logos section of the logo generator page") });
            rnd.E.classList.add("sw-push");
            const gen = el("section.sw-card.logo-gen", { attrs: { "aria-labelledby": "logo-gen-head" } },
                el("div.sw-card-head", null, genHead, rnd.E),
                el("div.sw-card-body", null, intro, list));
            document.body.append(el("main.sw-page-dash.logo-page", null, header.E, brand, gen));
            create();
            await pending.WaitAll();
        }
        catch (e) {
            //  Not allowed for this role (403): the shared "not allowed" state instead of a toast on an empty page
            if (Sw.Access && Sw.Access.IsDenied(e))
                Sw.Page.ShowNotAllowed({ Error: e });
            else
                Sw.Fail(e && e.message ? e.message : String(e), true);
        }
        finally {
            remove();
        }
    };
})();
